// Figma construction helpers. Token/variant setup follows the bundled
// createSemanticTokens.js and createComponentWithVariants.js patterns.
const createdNodeIds=[], mutatedNodeIds=[], styleJobs=[];
const fonts=[{family:'Inter',style:'Regular'},{family:'Inter',style:'Medium'},{family:'Inter',style:'Semi Bold'},{family:'Noto Sans SC',style:'Regular'},{family:'Noto Sans SC',style:'Medium'},{family:'Instrument Serif',style:'Italic'}];
await Promise.all(fonts.map(f=>figma.loadFontAsync(f)));
const localVars=await figma.variables.getLocalVariablesAsync();
const vars=Object.fromEntries(localVars.map(v=>[v.name,v]));
const localStyles=Object.fromEntries((await figma.getLocalTextStylesAsync()).map(s=>[s.name,s]));
const track=n=>{createdNodeIds.push(n.id);return n;};
const col=h=>({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});
const colors={paper:'#f7f7f4',ink:'#22231f',muted:'#777972',line:'#ddded7',signal:'#d84b20',sage:'#edf0e7',sageInk:'#728666',white:'#ffffff'};
const paint=k=>vars['color/'+k]?figma.variables.setBoundVariableForPaint({type:'SOLID',color:col(colors[k])},'color',vars['color/'+k]):{type:'SOLID',color:col(colors[k])};
function F(name,w,dir='VERTICAL',gap=0,fill=null){const f=track(figma.createAutoLayout(dir));f.name=name;f.resize(w,1);f.primaryAxisSizingMode=dir==='HORIZONTAL'?'FIXED':'AUTO';f.counterAxisSizingMode=dir==='HORIZONTAL'?'AUTO':'FIXED';f.itemSpacing=gap;f.fills=fill?[paint(fill)]:[];return f;}
function T(value,size=13,color='ink',width=0,style='Regular',family=null){value=String(value);family=family||(/[\u3400-\u9fff]/.test(value)?'Noto Sans SC':'Inter');const font={family,style};const key=`Plica/${family}/${size}/${style}`;let ts=localStyles[key];if(!ts){ts=figma.createTextStyle();ts.name=key;ts.fontName=font;ts.fontSize=size;ts.lineHeight={unit:'PERCENT',value:size>=64?102:size<30?165:140};localStyles[key]=ts;}const n=track(figma.createText());n.name=value.slice(0,45);n.fontName=font;n.fontSize=size;n.lineHeight=ts.lineHeight;n.characters=value;n.fills=[paint(color)];if(width){n.resize(width,Math.max(1,size*1.7));n.textAutoResize='HEIGHT';}else n.textAutoResize='WIDTH_AND_HEIGHT';styleJobs.push(n.setTextStyleIdAsync(ts.id));return n;}
function R(w,h,color='line'){const n=track(figma.createRectangle());n.resize(w,h);n.fills=[paint(color)];return n;}
function I(svg,size=18){const n=track(figma.createNodeFromSvg(svg));n.findAll(()=>true).forEach(x=>createdNodeIds.push(x.id));n.resize(size,size);return n;}
function pad(f,v,h=v){f.paddingTop=f.paddingBottom=v;f.paddingLeft=f.paddingRight=h;return f;}
function line(parent,width){parent.appendChild(R(width,1));}
function spacer(parent,h){const n=F('Space',1);n.resize(1,h);parent.appendChild(n);return n;}
function brand(){const f=F('Plica / Wordmark',110,'HORIZONTAL',10);f.counterAxisAlignItems='CENTER';const s=track(figma.createNodeFromSvg('<svg width="24" height="29" viewBox="0 0 24 29" xmlns="http://www.w3.org/2000/svg"><path d="M0 9 5 7v20L0 29zM8 4l5-2v25l-5 2zM16 2l5-2v19l-5 2z" fill="#d84b20"/></svg>'));f.appendChild(s);f.appendChild(T('Plica.',27,'ink',0,'Semi Bold'));return f;}
function eyebrow(value){const row=F('Eyebrow',350,'HORIZONTAL',10);row.counterAxisAlignItems='CENTER';row.appendChild(R(22,2,'signal'));row.appendChild(T(value,9,'muted'));return row;}
function frame(name,w,x,y){const f=F(name,w,'VERTICAL',0,'paper');f.x=x;f.y=y;f.clipsContent=false;return f;}
function header(parent,w,active='发现'){const h=F('Navigation',w,'VERTICAL',0,'paper');h.counterAxisAlignItems='CENTER';const inner=F('Navigation / Inner',w>700?1184:w-44,'HORIZONTAL',30);inner.resize(inner.width,w>700?78:65);inner.primaryAxisSizingMode='FIXED';inner.primaryAxisAlignItems='SPACE_BETWEEN';inner.counterAxisAlignItems='CENTER';inner.appendChild(brand());if(w>700){const links=F('Navigation / Pages',520,'HORIZONTAL',28);links.counterAxisAlignItems='CENTER';for(const label of ['发现','案例库','知识图谱','术语','论文']){const item=F('Nav / '+label,label.length*13+4,'VERTICAL',5);item.appendChild(T(label,12,label===active?'ink':'muted'));links.appendChild(item);}inner.appendChild(links);inner.appendChild(T('⌕ 搜索     ⌘ K      方案比较 ↗',11,'muted'));}else inner.appendChild(T('⌕      ☰',19,'muted'));h.appendChild(inner);line(h,w);parent.appendChild(h);return h;}
function body(parent,w){const b=F('Content',w>700?1184:w-44,'VERTICAL',0);parent.counterAxisAlignItems='CENTER';parent.appendChild(b);return b;}
function footer(parent,w){const f=F('Footer',w>700?1184:w-44,'VERTICAL',20);line(f,f.width);spacer(f,25);const r=F('Footer / Content',f.width,w>700?'HORIZONTAL':'VERTICAL',25);r.primaryAxisAlignItems='SPACE_BETWEEN';r.appendChild(brand());r.appendChild(T('案例库     研究论文     设计取舍     GitHub ↗',10,'muted'));r.appendChild(T('独立策展项目 · 原始资料版权归作者所有\n© 2026 Plica',9,'muted',w>700?260:w-44));f.appendChild(r);spacer(f,35);parent.appendChild(f);}
function heading(parent,kicker,title,description,w=1184){spacer(parent,60);parent.appendChild(eyebrow(kicker));spacer(parent,25);parent.appendChild(T(title,w>700?46:32,'ink',w,'Medium'));if(description){spacer(parent,17);parent.appendChild(T(description,12,'muted',Math.min(w,720)));}spacer(parent,40);}
function sectionTitle(parent,no,title,width){const r=F('Section / '+title,width,'HORIZONTAL',20);r.counterAxisAlignItems='CENTER';r.appendChild(T(no,10,'muted'));r.appendChild(T(title,23,'ink',width-90,'Medium'));parent.appendChild(r);spacer(parent,25);}
async function loadComponents(mapping){const entries=await Promise.all(Object.entries(mapping).map(async([k,id])=>[k,await figma.getNodeByIdAsync(id)]));return Object.fromEntries(entries);}
function instance(comp,parent,props={}){const n=track(comp.createInstance());parent.appendChild(n);if(Object.keys(props).length){const owner=comp.parent?.type==='COMPONENT_SET'?comp.parent:comp;const defs=owner.componentPropertyDefinitions;const values={};for(const [k,v] of Object.entries(props)){const full=Object.keys(defs).find(x=>x.split('#')[0]===k);if(full)values[full]=v;}n.setProperties(values);}return n;}
function atlas(parent,width,height,catalog,svg){const f=track(figma.createFrame());f.name='Atlas / Storage connections';f.resize(width,height);f.fills=[];parent.appendChild(f);const cx=width*.493,cy=height*.49;const positions=[[.25,.244],[.74,.276],[.821,.688],[.511,.84],[.153,.66]];const cs=catalog.cases.filter(c=>c.category==='storage').slice(0,5);const paths=positions.slice(0,cs.length).map(([x,y])=>`<path d="M${cx} ${cy} Q${(cx+x*width)/2} ${y*height} ${x*width} ${y*height}"/>`).join('');const lines=I(`<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg"><g fill="none" stroke="#c4c8ba" stroke-width="1">${paths}<circle cx="${cx}" cy="${cy}" r="${width*.23}" stroke-dasharray="2 8"/></g></svg>`,width);lines.resize(width,height);f.appendChild(lines);const center=F('Atlas / Mechanism',width>400?113:88,'VERTICAL',6,'signal');center.paddingTop=16;center.paddingBottom=16;center.counterAxisAlignItems='CENTER';center.cornerRadius=100;center.appendChild(I(svg.branch.replaceAll('currentColor','#ffffff'),width>400?27:21));center.appendChild(T('存储与数据',width>400?12:10,'white',0,'Medium'));center.appendChild(T('探索关联案例 ↗',8,'white'));f.appendChild(center);center.x=cx-center.width/2;center.y=cy-center.height/2;cs.forEach((c,i)=>{const n=F('Atlas / '+c.slug,width>400?142:104,'VERTICAL',4,'paper');n.strokes=[paint('line')];n.strokeWeight=1;n.cornerRadius=4;pad(n,9,10);n.appendChild(T(c.company,width>400?11:9,'ink',0,'Medium'));n.appendChild(T(c.title.slice(0,24)+'…',width>400?7:6,'muted',n.width-20));f.appendChild(n);n.x=positions[i][0]*width-n.width/2;n.y=positions[i][1]*height-n.height/2;});return f;}
async function finish(extra={}){await Promise.all(styleJobs);return {createdNodeIds,mutatedNodeIds,...extra};}
